const $=s=>document.querySelector(s),money=(n,c='GBP')=>new Intl.NumberFormat('en-GB',{style:'currency',currency:c,currencyDisplay:'code',maximumFractionDigits:2}).format(n),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const seed=()=>({name:'You',group:'The Together Club',funds:[{id:1,name:'Summer somewhere',desc:'A little sunshine, a lot of memories.',goal:3000,amount:1840,icon:'☀',members:8},{id:2,name:'Rainy day reserve',desc:'Peace of mind, shared by all of us.',goal:5000,amount:2750,icon:'☂',members:8},{id:3,name:'The big celebration',desc:'Making the next family milestone special.',goal:1500,amount:620,icon:'✧',members:6}],votes:[{id:1,title:'Book the Lake District cottage',amount:450,days:7,yes:4,no:1,voted:false,status:'Open'}],requests:[],contributions:[],messages:[{name:'Aisha',text:'Love seeing our summer fund growing. Where shall we go next?'},{name:'Daniel',text:'The Lake District gets my vote!'}],activity:['Welcome to your GroupFund test space.','New vote: Book the Lake District cottage','Summer somewhere reached 60% of its goal.'],privacy:'Members',joined:true});
let state;try{state=JSON.parse(localStorage.getItem('groupfund-demo-v1'))||seed()}catch{state=seed()}let view='overview',admin=false;function save(){try{localStorage.setItem('groupfund-demo-v1',JSON.stringify(state))}catch{} }function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3500)}function log(t){state.activity.unshift(t);save()}function heading(title,sub,action=''){return `<div class="heading"><div><div class="eyebrow">${esc(state.group.toUpperCase())}</div><h1>${title}</h1><p class="sub">${sub}</p></div>${action}</div>`}function fundCard(f){let pct=Math.min(100,Math.round(f.amount/f.goal*100));return `<article class="card"><div class="card-top"><div class="icon">${f.icon||'◈'}</div><span class="tag">${pct}% FUNDED</span></div><h3>${esc(f.name)}</h3><p>${esc(f.desc)}</p><div class="progress"><i style="width:${pct}%"></i></div><div class="amounts"><strong>${money(f.amount,f.currency)}</strong><span>of ${money(f.goal,f.currency)}</span></div><div class="row"><small>◉ ${f.members} saving together</small><small>Active fund</small></div><div class="actions"><button class="primary" data-action="contribute" data-id="${f.id}">+ Contribute</button><button data-action="withdraw" data-id="${f.id}">Withdraw</button></div></article>`}function activity(){return state.activity.slice(0,8).map(t=>`<div class="row"><p>↗ &nbsp; ${esc(t)}</p><small>Demo activity</small></div>`).join('')}function render(){document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#breadcrumb').textContent='Your workspace / '+({overview:'Overview',funds:'Our funds',votes:'Votes & requests',activity:'Activity',messages:'Messages',settings:'Settings'}[view]);$('#role').textContent=admin?'Switch to member':'Switch to admin';$('#badge').textContent=state.activity.length;let total=state.funds.reduce((a,f)=>a+f.amount,0),content='';
if(view==='overview')content=heading(`Good things start together.`,`Welcome back, ${esc(state.name)}. Here’s what your group is making possible.`,`<button class="primary" data-action="invite">+ Invite someone</button>`)+`<div class="hero"><div><div class="eyebrow" style="color:#b6cba8">SMALL STEPS. SHARED POSSIBILITIES.</div><h2 style="margin-top:15px">A shared goal.<br>A stronger circle.</h2><p>From the next family adventure to a little extra peace of mind. Make room for what matters, together.</p><button data-view="funds">Explore our funds ↗</button></div><div class="hero-art"><div class="ring">◈</div></div></div><div class="stats"><div class="stat"><small>Total saved together</small><strong>${money(total)}</strong><span>Across ${state.funds.length} shared goals</span></div><div class="stat"><small>People in your corner</small><strong>8 members</strong><span>Every contribution counts</span></div><div class="stat"><small>Open decisions</small><strong>${state.votes.filter(v=>v.status==='Open').length} vote</strong><span>Your voice matters</span></div></div><div class="section-title"><h2>Our shared goals</h2><button class="text-btn" data-view="funds">View all funds →</button></div><div class="grid">${state.funds.map(fundCard).join('')}</div><div class="two-col"><section class="card"><div class="section-title" style="margin-top:0"><h2>A little momentum</h2><button class="text-btn" data-view="activity">All activity →</button></div>${activity()}</section><section class="card"><span class="tag">HAVE YOUR SAY</span><h3>Decisions belong to all of us.</h3><p>One eligible contributing member, one vote. Help choose what happens next.</p><button data-view="votes">See open votes →</button><div class="notice">Approvals never move money automatically. An admin confirms every external payment.</div></section></div>`;
if(view==='funds')content=heading('Make room for the next goal.','Create a fund, join a goal, or add a little to something meaningful.',`<button class="primary" data-action="fund">+ Create a fund</button>`)+`<div class="tabs"><button data-action="group">Create group</button><button data-action="join">Join group</button><button data-action="joinfund">Request to join a fund</button></div><div class="grid">${state.funds.map(fundCard).join('')}</div><div class="notice">Fund creation and join requests go to the admin for approval. Use “Switch to admin” to test the other side of the journey.</div>`;
if(view==='votes')content=heading('A voice in what comes next.','Vote on shared decisions and keep approvals transparent.',`<button class="primary" data-action="proposal">+ Propose expense</button>`)+`<div class="notice">Voting lasts 3–14 days (default 7). Each eligible contributing member has one vote. This demo gives you a seeded contributor account. Admins can simulate closing a vote after its deadline.</div><div class="grid">${state.votes.map(v=>`<article class="card"><span class="tag">${esc(v.status)}</span><h3>${esc(v.title)}</h3><p>${money(v.amount,v.currency)} proposed · ${v.days}-day voting window</p><div class="progress"><i style="width:${Math.round(v.yes/(v.yes+v.no||1)*100)}%"></i></div><p>${v.yes} in favour · ${v.no} against</p>${v.status==='Open'?`<div class="vote-actions"><button data-action="yes" data-id="${v.id}" ${v.voted?'disabled':''}>${v.voted?'Vote recorded':'In favour'}</button><button data-action="no" data-id="${v.id}" ${v.voted?'disabled':''}>Against</button></div>${admin?`<button style="margin-top:15px" data-action="closevote" data-id="${v.id}">Simulate deadline & tally</button>`:''}`:'<p>Outcome recorded. Approved expenses await admin confirmation.</p>'}</article>`).join('')}</div><div class="section-title"><h2>Requests & verification</h2></div><div class="card">${state.contributions.filter(c=>c.status==='Pending').map(c=>`<div class="row"><div><strong>${money(c.amount,c.currency)} contribution</strong><p>${esc(c.fund)} · ${c.originalAmount?esc(money(c.originalAmount,c.originalCurrency))+' → ':''}${esc(money(c.amount,c.currency))} · Receipt: ${esc(c.receipt)}</p></div>${admin?`<div><button data-action="verify" data-id="${c.id}">Verify receipt</button> <button data-action="rejectreceipt" data-id="${c.id}">Request correction</button></div>`:'<span class="pill">Pending verification</span>'}</div>`).join('')}${state.requests.map(r=>`<div class="row"><div><strong>${esc(r.title)}</strong><p>${r.amount?money(r.amount,r.currency)+' · ':''}${esc(r.status)}</p></div>${admin&&r.status==='Pending approval'?`<div><button data-action="approve" data-id="${r.id}">Approve</button> <button data-action="reject" data-id="${r.id}">Reject</button></div>`:''}${admin&&r.status==='Approved — pending payment'?`<button data-action="pay" data-id="${r.id}">Confirm external payment</button>`:''}</div>`).join('')}${!state.requests.length&&!state.contributions.some(c=>c.status==='Pending')?'<div class="empty">All caught up. New requests will appear here.</div>':''}</div>`;
if(view==='activity')content=heading('Everything, in the open.','Your notifications and shared activity, in one place.')+`<div class="card">${activity()}</div><div class="tabs"><button data-view="votes">Open approvals & votes →</button><button data-view="messages">Open messages →</button></div>`;
if(view==='messages')content=heading('Keep the conversation going.','The Together Club · Group conversation')+`<div class="card">${state.messages.map(m=>`<div class="message"><small>${esc(m.name)}</small><p>${esc(m.text)}</p></div>`).join('')}<form id="message-form" class="inline"><input name="message" required maxlength="1000" aria-label="Message" placeholder="Share a thought with your group…"><button class="primary">Send →</button></form></div><div class="notice">Messages in this test edition are saved only in your browser. Other testers won’t see them.</div>`;
if(view==='settings')content=heading('Your space. Your preferences.','Manage your demo profile, group and privacy.')+`<div class="two-col"><div class="card"><h3>Profile & access</h3><p>Testing as ${esc(state.name)} · ${admin?'Admin':'Contributing member'}</p><div class="tabs"><button data-action="profile">Edit demo profile</button><button data-action="login">Demo registration / login</button></div><h3>Group</h3><p>${esc(state.group)}</p><div class="tabs"><button data-action="group">Create group</button><button data-action="join">Join group</button><button data-action="invite">Invite</button></div></div><div class="card"><h3>Contribution visibility</h3><p>Choose who sees your contribution details in this demo.</p><label for="privacy">Visibility</label><select id="privacy"><option ${state.privacy==='Members'?'selected':''}>Members</option><option ${state.privacy==='Admins only'?'selected':''}>Admins only</option></select><p>Admins retain verification access. Privacy controls are illustrative in this local demo.</p><label><input type="checkbox" style="width:auto" id="notifications" ${state.notifications!==false?'checked':''}> Show demo notification toasts</label></div></div>`;
$('#content').innerHTML=content;save();}
function modal(title,fields,fn){$('#modal-title').textContent=title;$('#fields').innerHTML=fields;$('#dialog').showModal();$('#form').onsubmit=e=>{e.preventDefault();let d=Object.fromEntries(new FormData(e.target));if(fn(d)!==false){$('#dialog').close();save();render()}}}function input(name,label,type='text',extra=''){return `<label>${label}<input name="${name}" type="${type}" required ${extra}></label>`}function request(title,amount=0,extra={}){state.requests.unshift({id:Date.now(),title,amount,status:'Pending approval',...extra});log(title+' submitted for approval');toast('Request sent to your admin')}
document.addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;if(b.dataset.view){view=b.dataset.view;render();window.scrollTo(0,0);return}let a=b.dataset.action,id=Number(b.dataset.id),f=state.funds.find(x=>x.id===id),v=state.votes.find(x=>x.id===id),r=state.requests.find(x=>x.id===id);if(!a)return;
if(a==='contribute')modal('Add a little momentum',`<p>Contribute to ${esc(f.name)}. Simulate transferring through your bank, then add a test receipt. Do not transfer real money.</p><div class="notice">DEMO BANK DETAILS · No real account provided.</div>${input('amount','Amount (£)','number','min="1" max="100000" step="1"')}${input('receipt','Test receipt filename or reference')}`,d=>{state.contributions.push({id:Date.now(),amount:+d.amount,fund:f.name,fundId:f.id,receipt:d.receipt,status:'Pending'});log('Contribution receipt submitted for '+f.name);toast('Receipt submitted — awaiting admin verification')});
if(a==='withdraw')modal('Request a withdrawal',`<p>${esc(f.name)} · Available ${money(f.amount,f.currency)}</p>${input('amount','Amount (£)','number',`min="1" max="${f.amount}"`)}${input('reason','Reason')}`,d=>request('Withdrawal: '+d.reason,+d.amount,{fundId:f.id}));
if(a==='fund')modal('A new shared goal',input('name','Fund name')+input('desc','What are you saving for?')+input('goal','Target (£)','number','min="1" max="1000000"'),d=>request('Create fund: '+d.name,0,{fund:d}));
if(a==='joinfund')modal('Join a shared goal',`<label>Fund<select name="fund">${state.funds.map(f=>`<option>${esc(f.name)}</option>`).join('')}</select></label>`,d=>request('Join fund: '+d.fund));
if(a==='group')modal('Create your circle',input('name','Group name')+input('purpose','Group purpose')+'<label>Invitation emails (optional)<input name="invites" placeholder="Invite later, or enter test emails"></label>',d=>{state.group=d.name;log('Group created: '+d.name);toast('Group created. You can invite people later.')});
if(a==='join')modal('Join your people',input('code','Group invitation code','text','placeholder="Try TOGETHER"')+'<p>Use TOGETHER to join the sample group.</p>',d=>{if(d.code.trim().toUpperCase()!=='TOGETHER'){toast('Use the demo code TOGETHER');return false}state.group='The Together Club';log('You joined The Together Club');toast('Welcome to the group')});
if(a==='invite')modal('Better with your people',`<p>Share the website URL with your tester. Demo group code: <strong>TOGETHER</strong>.</p><p>This prototype does not send invitation emails or sync groups between devices.</p><label>Test invitation email (optional)<input name="email" type="email"></label>`,d=>{log('Demo invitation prepared');toast('Invitation simulated — share the website link')});
if(a==='profile'||a==='login')modal(a==='login'?'Try the account journey':'Your demo profile',input('name','Display name','text',`value="${esc(state.name)}"`)+'<p>No password needed. This creates a local test profile, not a secure online account.</p>',d=>{state.name=d.name;toast('Demo profile saved')});
if(a==='proposal')modal('Put an idea to the group',input('title','Expense / proposal title')+input('amount','Amount (£)','number','min="1"')+input('days','Voting duration (3–14 days)','number','min="3" max="14" value="7"'),d=>{state.votes.unshift({id:Date.now(),title:d.title,amount:+d.amount,days:+d.days,yes:0,no:0,voted:false,status:'Open'});log('New vote: '+d.title)});
if(a==='yes'||a==='no'){if(v.voted||v.status!=='Open')return;v[a]++;v.voted=true;log('Your vote was recorded');toast('One member, one vote. Yours is recorded.');render()}
if(!admin)return;
if(a==='closevote'){if(v.status!=='Open')return;v.status=v.yes>v.no?'Approved':'Not passed';if(v.status==='Approved')state.requests.push({id:Date.now(),title:'Expense: '+v.title,amount:v.amount,fundId:v.fundId||1,currency:v.currency||'GBP',status:'Approved — pending payment'});log('Vote closed: '+v.title+' — '+v.status);render()}
if(a==='verify'||a==='rejectreceipt'){let c=state.contributions.find(x=>x.id===id);if(c.status!=='Pending')return;c.status=a==='verify'?'Verified':'Correction requested';if(a==='verify')state.funds.find(f=>f.id===c.fundId).amount=Math.round((state.funds.find(f=>f.id===c.fundId).amount+c.amount)*100)/100;log('Receipt '+c.status.toLowerCase()+': '+c.fund);render()}
if(a==='approve'){if(r.fund){state.funds.push({id:Date.now(),name:r.fund.name,desc:r.fund.desc,goal:+r.fund.goal,amount:0,icon:'◈',members:1,currency:r.fund.currency||'GBP',type:r.fund.type,monthly:r.fund.monthly,people:r.fund.people});r.status='Approved'}else r.status=r.amount?'Approved — pending payment':'Approved';log(r.title+' approved');render()}
if(a==='reject'){r.status='Rejected';log(r.title+' rejected');render()}
if(a==='pay')modal('Confirm completed external payment',`<p>${esc(r.title)} · ${money(r.amount,r.currency)}</p><div class="notice">Demo simulation only. In the real product, an admin transfers externally, then records the completed payment here.</div>${input('reference','Test payment reference')}`,d=>{let fund=state.funds.find(f=>f.id===r.fundId);if(fund&&fund.amount<r.amount){toast('Insufficient fund balance');return false}if(fund)fund.amount-=r.amount;r.status='Paid (demo)';r.reference=d.reference;log('Admin confirmed external payment: '+r.title);toast('Demo payment recorded')});
});
$('#close').onclick=()=>$('#dialog').close();$('#role').onclick=()=>{admin=!admin;render();toast(admin?'Testing as admin':'Testing as member')};$('#reset').onclick=()=>modal('Reset your test space','<p>This replaces demo activity in this browser with the original sample data.</p>',()=>{state=seed();view='overview';toast('Fresh start — demo reset')});document.addEventListener('change',e=>{if(e.target.id==='privacy'){state.privacy=e.target.value;save();toast('Privacy preference saved')}if(e.target.id==='notifications'){state.notifications=e.target.checked;save()}});document.addEventListener('submit',e=>{if(e.target.id!=='message-form')return;e.preventDefault();let text=new FormData(e.target).get('message').trim();if(!text)return;state.messages.push({name:state.name,text});log('New message from '+state.name);render()});render();

// Friendly family journeys and currency-aware records. Existing GBP balances retain their currency.
state.funds.forEach(f=>f.currency=f.currency||'GBP');
const currencies=[...new Set(['MYR','GBP','SGD','USD','EUR',...(Intl.supportedValuesOf?Intl.supportedValuesOf('currency'):['AUD','CAD','NZD','JPY','INR','IDR','AED','SAR','THB','CNY'])])];
function currencySelect(name,selected='MYR'){return `<label>${name==='currency'?'Fund currency — the currency for its total':'Currency you are sending'}<select name="${name}">${currencies.map(c=>`<option ${c===selected?'selected':''}>${c}</option>`).join('')}</select></label>`}
let wizard={type:'family',currency:'MYR'},step=1;
const originalRender=render;
render=function(){originalRender();document.querySelectorAll('nav button').forEach(b=>{const labels={overview:'Home',funds:'Family funds',votes:'Votes & approvals',activity:'Updates',messages:'Family chat',settings:'My settings'};b.textContent=labels[b.dataset.view]});$('#breadcrumb').textContent=admin?'Family test space · Admin view':'Family test space · Member view';$('.workspace').innerHTML=esc(state.group)+'<br><small>Across countries. Still together.</small>';$('.demo').querySelector('span').textContent='Practice only. Nothing is sent to a bank. Each person has their own demo data.';
if(view==='overview'){$('#content').innerHTML=heading(`Hello, ${esc(state.name)}.`,`What would you like to do today?`)+`<div class="quick-actions"><button data-view="funds"><strong>1. See our family funds</strong><span>Choose a fund and add money</span></button><button data-action="friendly-start"><strong>2. Start a new fund</strong><span>I’ll guide you, one step at a time</span></button><button data-view="messages"><strong>3. Talk to the family</strong><span>Read or write a message</span></button></div><section class="welcome-card"><div><span class="tag">NEW HERE? START HERE</span><h2>One family. Wherever you live.</h2><p>You can contribute in pounds from the UK while Mum contributes in ringgit from Malaysia. Your family chooses one currency for each fund’s total.</p><button class="primary" data-action="friendly-start">Help me choose a fund →</button><button data-action="help">How does this work?</button></div><div class="country-example"><strong>UK · GBP</strong><span>↓</span><strong>Our family fund · MYR</strong><span>↑</span><strong>Malaysia · MYR</strong><small>Conversion is reviewed before it is recorded.</small></div></section><div class="section-title"><h2>Your family funds</h2><button data-view="funds">See all →</button></div><div class="grid">${state.funds.map(fundCard).join('')}</div><div class="notice">Need to approve something? Open <button data-view="votes">Votes & approvals</button>. For testing the admin’s side, use “Switch to admin” at the top.</div>`;}
if(view==='funds'){$('.heading h1').textContent='Your family funds';$('.heading .sub').textContent='Choose a fund below. Then tap “Add money”.';}
$('#content').querySelectorAll('[data-action="fund"]').forEach(b=>b.textContent='Start a fund — guided setup');$('#content').querySelectorAll('[data-action="contribute"]').forEach(b=>b.textContent='Add money');$('#content').querySelectorAll('[data-action="withdraw"]').forEach(b=>b.textContent='Ask to take money out');
$('#content').querySelectorAll('.card').forEach(card=>{let btn=card.querySelector('[data-action="contribute"]');if(!btn)return;let f=state.funds.find(f=>f.id===+btn.dataset.id);if(f?.type==='kutu'){let p=document.createElement('p');p.textContent=`Kutu-style plan · ${f.people} people · ${money(f.monthly,f.currency)} per person each month. Payout order must be agreed with your family.`;card.append(p)}});
if(view==='votes'){let box=document.createElement('section');box.className='card';box.innerHTML='<h2>Your contribution history</h2>'+ (state.contributions.map(c=>`<div class="row"><div><strong>${esc(c.fund)}</strong><p>${money(c.originalAmount||c.amount,c.originalCurrency||c.currency)}${c.originalCurrency&&c.originalCurrency!==c.currency?' → '+money(c.amount,c.currency):''}</p><small>${esc(c.rateSource||'Same currency')} · ${esc(c.status)}</small></div>${c.status==='Correction requested'?`<button data-action="resubmit" data-id="${c.id}">Fix receipt</button>`:''}</div>`).join('')||'<p>No contributions yet. Choose a fund, then tap Add money.</p>');$('#content').append(box)}
};
function showWizard(){modal(`Start a family fund · Step ${step} of 3`,step===1?`<p>Choose the plan that sounds right for your family. You can go back at any time.</p><label class="choice"><input type="radio" name="type" value="family" ${wizard.type==='family'?'checked':''}> <strong>Family savings — a simple place to start</strong><span>Save towards a holiday, emergency or shared goal. Everyone adds what they can.</span></label><label class="choice"><input type="radio" name="type" value="kutu" ${wizard.type==='kutu'?'checked':''}> <strong>Kutu-style savings circle</strong><span>Everyone contributes a fixed amount regularly. One person receives the pot each round, in an agreed order. This demo helps plan the circle; it does not operate payouts.</span></label>`:step===2?`${input('name','What shall we call this fund?','text',`value="${esc(wizard.name||'')}" placeholder="e.g. Our family savings"`)}${currencySelect('currency',wizard.currency)}<p>Choose MYR if your family wants to track its total in Malaysian ringgit. Contributions can still come from other currencies.</p>${input('goal','Savings target (in the fund currency)','number',`min="1" max="100000000" step="0.01" value="${wizard.goal||''}"`)}${wizard.type==='kutu'?input('monthly','Each person contributes per month (fund currency)','number',`min="1" step="0.01" value="${wizard.monthly||''}"`)+input('people','Number of people / monthly rounds','number',`min="2" max="100" value="${wizard.people||''}"`):''}`:`<p>Check your plan before sending it to the family admin.</p><div class="notice"><strong>${esc(wizard.name)}</strong><br>${wizard.type==='kutu'?'Kutu-style circle':'Family savings'}<br>Target: ${money(+wizard.goal,wizard.currency)}<br>Fund currency: ${wizard.currency}${wizard.type==='kutu'?`<br>${wizard.people} people · ${money(+wizard.monthly,wizard.currency)} each per month<br>Planned monthly pot: ${money(+wizard.monthly*+wizard.people,wizard.currency)}<br>Agree the recipient order and missed-payment rules with everyone before starting.`:''}</div><p>Members abroad can contribute in their own currency. The admin verifies the amount actually received in ${wizard.currency}.</p>`,d=>{Object.assign(wizard,d);if(step<3){step++;queueMicrotask(showWizard);return true}request('Create fund: '+wizard.name,0,{fund:{...wizard,desc:wizard.type==='kutu'?'A family savings circle with an agreed monthly contribution.':'A shared family goal, wherever we live.'}});wizard={type:'family',currency:'MYR'};view='votes';});$('#form > .primary').textContent=step===3?'Send to family admin':'Next step →';if(step>1){let back=document.createElement('button');back.type='button';back.textContent='← Back';back.onclick=()=>{Object.assign(wizard,Object.fromEntries(new FormData($('#form'))));$('#dialog').close();step--;showWizard()};$('#fields').append(back)}}
function contribution(f){modal('Add money · '+f.name,`<ol class="steps"><li>Enter the amount and currency you are sending.</li><li>Record how much reaches the fund after conversion and fees.</li><li>Add a test receipt. The admin checks it before the total changes.</li></ol><p>This is a practice payment. Do not send real money.</p>${input('originalAmount','Amount you are sending','number','min="0.01" max="100000000" step="0.01"')}${currencySelect('originalCurrency',state.sendCurrency||'GBP')}<button type="button" id="estimate">Show reference conversion</button><p id="estimate-text" role="status">Fund total is in ${f.currency}. Reference rates are estimates; your bank’s rate and fees may differ.</p>${input('received',`Amount received by the fund (${f.currency})`,'number','min="0.01" max="100000000" step="0.01"')}<p>Use the amount shown on your transfer receipt. If currencies differ, this may be different from the reference estimate.</p>${input('receipt','Test receipt name or transfer reference')}`,d=>{let original=+d.originalAmount,received=+d.received;if(d.originalCurrency===f.currency&&Math.abs(original-received)>.005){toast('For the same currency, enter the same amount in both boxes.');return false}state.sendCurrency=d.originalCurrency;state.contributions.push({id:Date.now(),amount:received,currency:f.currency,originalAmount:original,originalCurrency:d.originalCurrency,rate:received/original,rateSource:d.originalCurrency===f.currency?'Same currency':'Receipt amount entered by member; admin verification required',recordedAt:new Date().toISOString(),fund:f.name,fundId:f.id,receipt:d.receipt,status:'Pending'});log(`Receipt submitted: ${money(original,d.originalCurrency)} → ${money(received,f.currency)}`);view='votes';toast('Sent to admin. Your fund total changes after verification.')});$('#form > .primary').textContent='Send receipt to admin';let form=$('#form');form.elements.originalAmount.oninput=()=>{if(form.elements.originalCurrency.value===f.currency)form.elements.received.value=form.elements.originalAmount.value};form.elements.originalCurrency.onchange=()=>{form.elements.received.value='';if(form.elements.originalCurrency.value===f.currency)form.elements.received.value=form.elements.originalAmount.value;$('#estimate-text').textContent='Currency changed. Check the amount received again.'};$('#estimate').onclick=async()=>{let from=form.elements.originalCurrency.value,amount=+form.elements.originalAmount.value;if(!(amount>0)){toast('Enter your amount first');return}$('#estimate-text').textContent='Checking reference rate…';try{let rate=1,date='same currency';if(from!==f.currency){let response=await fetch(`https://api.frankfurter.dev/v2/rate/${from}/${f.currency}`,{signal:AbortSignal.timeout(8000)});if(!response.ok)throw Error();let data=await response.json();rate=Number(data.rate);date=data.date;if(!(rate>0))throw Error()}let result=Math.round(amount*rate*100)/100;$('#estimate-text').textContent=`Reference estimate: ${money(amount,from)} ≈ ${money(result,f.currency)}. Rate date: ${date}. Source: Frankfurter. Enter the actual amount received below; fees are not included.`}catch{$('#estimate-text').textContent='Reference rate unavailable. You can still enter the actual amount received from your test receipt. No guessed rate will be used.'}};}
document.addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;let a=b.dataset.action,f=state.funds.find(f=>f.id===+b.dataset.id);if(!['friendly-start','fund','help','contribute','withdraw','proposal','resubmit'].includes(a))return;e.stopImmediatePropagation();if(a==='friendly-start'||a==='fund'){step=1;showWizard()}if(a==='help')modal('Three simple steps','<ol class="steps"><li><strong>Choose a family fund.</strong> Or start one with our guided setup.</li><li><strong>Add money in your currency.</strong> Record the amount the fund receives and a test receipt.</li><li><strong>The admin checks it.</strong> Then the fund total updates. You can find decisions in Votes & approvals.</li></ol><p>To try the admin side, use Switch to admin. No real transfers happen here.</p>',()=>{});if(a==='contribute')contribution(f);if(a==='withdraw')modal('Ask to take money out',`<p>${esc(f.name)} · Available ${money(f.amount,f.currency)}</p>${input('amount',`Amount (${f.currency})`,'number',`min="0.01" max="${f.amount}" step="0.01"`)}${input('reason','What is the money for?')}`,d=>request('Withdrawal: '+d.reason,+d.amount,{fundId:f.id,currency:f.currency}));if(a==='proposal')modal('Ask the family to vote',`<label>Which fund?<select name="fundId">${state.funds.map(f=>`<option value="${f.id}">${esc(f.name)} (${f.currency})</option>`).join('')}</select></label>${input('title','What would you like to pay for?')}${input('amount','Amount (in the selected fund’s currency)','number','min="0.01" step="0.01"')}${input('days','Days for family to vote (3–14)','number','min="3" max="14" value="7"')}`,d=>{let f=state.funds.find(f=>f.id===+d.fundId);state.votes.unshift({id:Date.now(),title:d.title,amount:+d.amount,currency:f.currency,fundId:f.id,days:+d.days,yes:0,no:0,voted:false,status:'Open'});log('New vote: '+d.title)});if(a==='resubmit'){let c=state.contributions.find(c=>c.id===+b.dataset.id);modal('Fix your receipt',input('receipt','Corrected test receipt / reference'),d=>{c.receipt=d.receipt;c.status='Pending';log('Corrected receipt sent to admin')})}},true);
render();
